from openpyxl import load_workbook
wb = load_workbook('/root/gdp_constant.xlsx')
print('Sheets:', wb.sheetnames)
ws = wb[wb.sheetnames[0]]

# Find column indices for years
year_cols = {}
for col in range(1, ws.max_column + 1):
    header = ws.cell(row=2, column=col).value
    if header and (isinstance(header, int) or (isinstance(header, str) and header.isdigit())):
        year = int(header)
        if year >= 2018:
            year_cols[year] = col

print('Year columns:', sorted(year_cols.items()))

# Find GDP row
for row in range(1, ws.max_row + 1):
    cell_val = ws.cell(row=row, column=2).value
    if cell_val and 'GDP at market prices' in str(cell_val):
        print(f'Found GDP row at row {row}: {cell_val}')
        for year, col in sorted(year_cols.items()):
            val = ws.cell(row=row, column=col).value
            print(f'{year}: {val}')
